  disposables.push(borderGeo);

  const borderMat = new THREE.LineBasicMaterial({ color: 0x26262f, linewidth: 1 });
  disposables.push(borderMat);

  const border = new THREE.LineLoop(borderGeo, borderMat);
  border.position.z = 0;
  group.add(border);

  // ─ Ghost preview (left of center) ─
  const ghostGroup = new THREE.Group();
  ghostGroup.position.x = -0.7;

  // Watch card wireframe: 1.1w × 1.4h
  const cardGeo = createRectGeometry(1.1, 1.4);
  const cardMat = new THREE.LineBasicMaterial({
    color: 0xe8ecf2,
    transparent: true,
    opacity: 0.3,
    linewidth: 1
  });
  disposables.push(cardGeo, cardMat);
  const cardLine = new THREE.LineLoop(cardGeo, cardMat);
  ghostGroup.add(cardLine);

  // Dial circle (0.55 diameter)
  const dialGeo = createCircleGeometry(0.275, 48);
  const dialMat = new THREE.LineBasicMaterial({
    color: 0xe8ecf2,
    transparent: true,
