  // Ghost breathing animation: 0.24 → 0.34 over 2400ms cubic-bezier
  const breathTl = gsap.timeline({ repeat: -1, yoyo: true });
  breathTl.to(ghostGroup, {
    opacity: 0.34,
    duration: 1.2,
