  }, 0);
  breathTl.to(ghostGroup, {
    opacity: 0.24,
    duration: 1.2,
    ease: 'cubic-bezier(0.445,0.05,0.55,0.95)'
  });
  timelines.push(breathTl);

  // ─ Text column (right of center, 0.5 padding) ─
  const textX = 0.5;

  // Headline: "Your ledger is empty." (Lora 600, 34px scale → 0.34 scene units)
  const headline = ctx.fontAtlas.createText(
