  headline.position.set(textX, 0.35, 0);
  group.add(headline);
  disposables.push(headline.geometry, headline.material);

  // Body: "Commissioned pieces..." (JetBrains Mono 400, 13px → 0.13)
  const body = ctx.fontAtlas.createText(
