    }
  );
  body.position.set(textX, -0.05, 0);
  group.add(body);
  disposables.push(body.geometry, body.material);

  // ─ CTA Button (1.5w × 0.36h, vertical gradient) ─
  const btnGeo = new THREE.PlaneGeometry(1.5, 0.36);
  disposables.push(btnGeo);

  const btnMat = new THREE.MeshBasicNodeMaterial({
