    timelines.forEach(tl => tl.kill());
    disposables.forEach(item => {
      if (item.dispose) item.dispose();
    });
  };

  return group;
}

function createGradientGridNode() {
  // Radial gradient #14141a (center, at 0.0) → #0b0b10 (edges, at 1.0)
  // Grid: 0.25-unit pitch in #e8ecf2 at 6% opacity
  const posLength = length();
  const maxDist = Math.sqrt(3.2 * 3.2 + 2.2 * 2.2) / 2;
  const gradT = posLength.div(maxDist).clamp(0, 1);

  const grad = mix(color(0x14141a), color(0x0b0b10), gradT);

  // Grid pattern at 0.25 pitch (frequency = 4)
  const gridFreq = 4;
  const gridX = sin(posLength.x.mul(gridFreq * PI));
  const gridY = sin(posLength.y.mul(gridFreq * PI));
  const gridMask = gridX.mul(gridY).abs().lessThan(0.1);
  const grid = color(0xe8ecf2).mul(0.06).mul(gridMask);

  return grad.add(grid);
}

function createRectGeometry(w, h) {
  const points = new Float32Array([
    w / 2, h / 2, 0,
    -w / 2, h / 2, 0,
    -w / 2, -h / 2, 0,
    w / 2, -h / 2, 0
  ]);
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(points, 3));
  return geo;
}

function createCircleGeometry(r, segments) {
  const points = [];
  for (let i = 0; i <= segments; i++) {
    const angle = (i / segments) * Math.PI * 2;
    points.push(r * Math.cos(angle), r * Math.sin(angle), 0);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(points), 3));
  return geo;
}

function createRoundedRectGeometry(w, h, r, segsPerCorner = 12) {
  const points = [];
  const hW = w / 2;
  const hH = h / 2;

  // Top-right corner
  for (let i = 0; i <= segsPerCorner; i++) {
    const t = i / segsPerCorner;
    const angle = -t * Math.PI / 2;
    points.push(hW - r + r * Math.cos(angle), hH - r + r * Math.sin(angle), 0);
  }

  // Top-left corner
  for (let i = 1; i <= segsPerCorner; i++) {
    const t = i / segsPerCorner;
    const angle = Math.PI / 2 - t * Math.PI / 2;
    points.push(-hW + r + r * Math.cos(angle), hH - r + r * Math.sin(angle), 0);
  }

  // Bottom-left corner
  for (let i = 1; i <= segsPerCorner; i++) {
    const t = i / segsPerCorner;
    const angle = Math.PI - t * Math.PI / 2;
    points.push(-hW + r + r * Math.cos(angle), -hH + r + r * Math.sin(angle), 0);
  }

  // Bottom-right corner
  for (let i = 1; i <= segsPerCorner; i++) {
    const t = i / segsPerCorner;
    const angle = 3 * Math.PI / 2 - t * Math.PI / 2;
    points.push(hW - r + r * Math.cos(angle), -hH + r + r * Math.sin(angle), 0);
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(points), 3));
  return geo;
}
